const newFM = { id: "FM-"+..., parcela, hectareas: ha, especie, numArboles: arboles, alturaPromedioM: altura, dapPromedioCm: dap, volumenManualM3: volumen, fecha: "10/05/2024", responsable: store.getCurrentUser().nombre };
